def fibonacci_memoization(n):
    # Use a global dictionary for memoization
    memo = {}

    def fib_inner(k):
        if k < 0:
            raise ValueError("n must be non-negative")
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 0
            return 0
        if k == 1:
            memo[k] = 1
            return 1
        # Thread-safe access to memo via global dictionary
        result = fib_inner(k - 1)
        result += fib_inner(k - 2)
        memo[k] = result
        return result

