def right_view(tree):
    if not tree:
        return []

    result = []
    # Use a stack to simulate level-order traversal
    # We only need to process the rightmost node at each level.
    stack = [tree]
    while stack:
        level_size = len(stack)
        for _ in range(level_size):
            node = stack.pop()
            # If this is the first node encountered in the current level,
            # it will be the rightmost node for that level.
            if not stack:
                result.append(node.val)
            # Push right child first so that when we pop, we get the rightmost node
