def convert_date_to_compact_format(dates):
    def is_valid_date(date_str):
        try:
            year, month, day = map(int, date_str.split('-'))
            if not (1 <= month <= 12 and 1 <= day <= 31):
                return False
            # Simple leap year check for validity
            if month in [4, 6, 9, 11] and day > 30:
                return False
            if month in [2] and (year % 4 != 0 or (year % 100 == 0 and year % 400 != 0)) and day > 29:
                return False
            return True
        except (ValueError, AttributeError):
            return False

